import{_ as e,c as a,a0 as l,o as s}from"./chunks/framework.BGabeMLJ.js";const f=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/glossar.md","filePath":"getting-started/glossar.md"}'),r={name:"getting-started/glossar.md"};function n(i,t,d,o,g,y){return s(),a("div",null,t[0]||(t[0]=[l('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Term</th><th style="text-align:left;">Explanation</th></tr></thead><tbody><tr><td style="text-align:left;">Aggregation protocol</td><td style="text-align:left;">Algorithm code how final/online results are computed</td></tr><tr><td style="text-align:left;">Aggregator</td><td style="text-align:left;">Node of an analysis that combines the results of the analyzers, decides in iterative analyses whether another round is needed, and submits the final result to the Hub</td></tr><tr><td style="text-align:left;">Analysis</td><td style="text-align:left;">Docker containers containing algorithm, analysis logic and software dependencies</td></tr><tr><td style="text-align:left;">Analyzer</td><td style="text-align:left;">Node of an analysis that executes the analysis code on its local data and sends its result to the aggregator</td></tr><tr><td style="text-align:left;">Authup</td><td style="text-align:left;">Identity and access management service of the Hub, managing realms, users, roles, clients and permissions</td></tr><tr><td style="text-align:left;">Bucket</td><td style="text-align:left;">Storage location for files in an S3 object store. A bucket is connected to a project as a data store</td></tr><tr><td style="text-align:left;">Checkpoint</td><td style="text-align:left;">Saved state of an analysis in the local storage of a node, from which a later analysis of the same project can resume</td></tr><tr><td style="text-align:left;">Client</td><td style="text-align:left;">Technical account for automated access to the Hub API, which cannot log in to the user interface (formerly <em>robot</em>)</td></tr><tr><td style="text-align:left;">Core SDK</td><td style="text-align:left;">Python library (<code>FlameCoreSDK</code>) through which analysis code accesses data, exchanges messages with other nodes and submits results</td></tr><tr><td style="text-align:left;">Data discovery</td><td style="text-align:left;">Pre-analysis to verify biases, schemas or any other unexpected behavior by sites</td></tr><tr><td style="text-align:left;">Data steward</td><td style="text-align:left;">Role at a node that may create and modify data stores, but not start or stop analyses</td></tr><tr><td style="text-align:left;">Data store</td><td style="text-align:left;">Configuration at a node that maps a project to a data source of the site, either a FHIR server or an S3 bucket</td></tr><tr><td style="text-align:left;">DIC</td><td style="text-align:left;">Data Integration Center. Unit at a university hospital of the MII that provides clinical data for research</td></tr><tr><td style="text-align:left;">Differential privacy</td><td style="text-align:left;">Technique that adds calibrated noise to a result, so that it reveals less about individual persons</td></tr><tr><td style="text-align:left;">Federated Learning</td><td style="text-align:left;">Parallel execution of analysis code at multiple sites, at the same time with a global result aggregation</td></tr><tr><td style="text-align:left;">FHIR</td><td style="text-align:left;">Fast Healthcare Interoperability Resources</td></tr><tr><td style="text-align:left;">FHIR Core</td><td style="text-align:left;">Common data schema developed by MII to be fulfilled by each DIC</td></tr><tr><td style="text-align:left;">Final results</td><td style="text-align:left;">Results achieved by aggregator, can be encrypted project specific</td></tr><tr><td style="text-align:left;">FLAME</td><td style="text-align:left;">Federated Learning and Analysis In Medicine</td></tr><tr><td style="text-align:left;">Harbor</td><td style="text-align:left;">Container image registry of the Hub. Analysis images are distributed to the nodes through a separate project per node</td></tr><tr><td style="text-align:left;">Homomorphic encryption</td><td style="text-align:left;">Encryption scheme that allows computing on encrypted values without decrypting them</td></tr><tr><td style="text-align:left;">Hub</td><td style="text-align:left;">All service components centrally hosted and operated</td></tr><tr><td style="text-align:left;">Identity provider</td><td style="text-align:left;">External login service (OIDC) that can be connected to a realm, so users log in with their existing account</td></tr><tr><td style="text-align:left;">Intermediate results</td><td style="text-align:left;">Results stored during an analysis, either locally on a node or on the Hub, encrypted for the receiving nodes</td></tr><tr><td style="text-align:left;">Kong</td><td style="text-align:left;">API gateway of a node through which an analysis accesses the data stores of its project</td></tr><tr><td style="text-align:left;">Master image</td><td style="text-align:left;">Base container image providing the runtime and software dependencies on which an analysis is built</td></tr><tr><td style="text-align:left;">Message broker</td><td style="text-align:left;">Service that relays messages between the nodes of an analysis through the Hub</td></tr><tr><td style="text-align:left;">MII</td><td style="text-align:left;">Medical Informatics Initiative. German funding program in which PrivateAIM is a project</td></tr><tr><td style="text-align:left;">Nodes</td><td style="text-align:left;">Hospitals hosting a node to provide analysis controlled and secure access to patient data</td></tr><tr><td style="text-align:left;">Paillier - key</td><td style="text-align:left;">This is the key to a homomorphic encryption system to additionally secure the calculated data inside the analysis</td></tr><tr><td style="text-align:left;">Permission</td><td style="text-align:left;">Predefined action in the Hub that is granted to users through roles</td></tr><tr><td style="text-align:left;">PrivateAIM</td><td style="text-align:left;">Project within the MII that develops the FLAME platform</td></tr><tr><td style="text-align:left;">Project</td><td style="text-align:left;">Current name of a proposal in the Hub user interface, see <em>Proposal</em></td></tr><tr><td style="text-align:left;">Proposal</td><td style="text-align:left;">A Proposal is an organizational unit in FLAME, which represents the collaboration between different participants in regard to a specific research or analysis project. It contains an initial risk assessment as well as a high level description of the requested data.</td></tr><tr><td style="text-align:left;">Proxy</td><td style="text-align:left;">Node of an analysis without data that pre-aggregates the results of its assigned analyzers, so the aggregator never sees the result of a single node (<code>ProxyModel</code>)</td></tr><tr><td style="text-align:left;">Realm</td><td style="text-align:left;">Administrative namespace in the Hub representing one organization, with its own users, roles, identity providers and nodes</td></tr><tr><td style="text-align:left;">Registry</td><td style="text-align:left;">Service to distribute analysis</td></tr><tr><td style="text-align:left;">Result inspection</td><td style="text-align:left;">Before results are returned these should be approved by sites to not contain unauthorized information</td></tr><tr><td style="text-align:left;">Role</td><td style="text-align:left;">Named set of permissions that is assigned to users</td></tr><tr><td style="text-align:left;">RSA - key</td><td style="text-align:left;">This is the key to a homomorphic encryption system to secure the analysis from external influences</td></tr><tr><td style="text-align:left;">S3</td><td style="text-align:left;">Object storage interface. FLAME reads files such as CSV or VCF from S3 buckets</td></tr><tr><td style="text-align:left;">Star pattern</td><td style="text-align:left;">Analysis topology in which every analyzer reports to one aggregator (<code>StarModel</code>)</td></tr><tr><td style="text-align:left;">UI</td><td style="text-align:left;">User Interface</td></tr></tbody></table>',2)]))}const h=e(r,[["render",n]]);export{f as __pageData,h as default};
